import { area, beam, buff, cleanse, defend, guard, heal, hit, shot } from './rules.js';

// Explicit three-slot choices, with bibliography reused only by exact ID.
// Named equipment, role actions and local avatars remain separate claims;
// numerical rules are adaptations and no source animation is certified.
const kit = (id, simple, secondary, defense, sourceReference, identityBasis = 'canonical-role') => {
  const source = CAPABILITIES_LOT_4[id];
  return {
    universe: source.universe, sourceWork: source.sourceWork, sourceReference,
    sourceUrl: source.sourceUrl || null, identityBasis,
    canonicalVerified: false, networkVerified: false, gameplayAdaptation: true,
    simple, secondary: { cd: 6, ...secondary }, defense
  };
};

